WITH filtered AS (SELECT id, order_id, amount, WEEKOFYEAR(paid_at) paid_at_weekofyear, LOWER(method) method_lower FROM payments WHERE order_id IS NOT NULL AND status IN ('SUCCESS', 'REFUNDED')) SELECT id, order_id, paid_at_weekofyear, method_lower, LAG(amount) OVER w_running prev_amount, LEAD(paid_at_weekofyear) OVER w_running next_paid_at_weekofyear, ROW_NUMBER() OVER w_running row_seq, RANK() OVER w_ordered amount_rank FROM filtered WINDOW w_running AS (PARTITION BY order_id ORDER BY amount, id), w_ordered AS (PARTITION BY order_id ORDER BY amount DESC);
